'use strict';
/* Component lab for the UI components page (#ux).
   64 native HTML/CSS components replace the raster previews (C41–C64 are fully interactive). Each one is drawn in every
   state it supports, in any of the 20 Atlas themes, light or dark, comfortable or compact.
   The code tab exports exactly the HTML and CSS the stage renders. */
