 let UID=0;
 // Labels point at their control and messages are wired with aria-describedby, so every field has a name.
 const field=(label,inner,hint='',err='')=>{const id='clf'+(++UID),m=err||hint?` aria-describedby="${id}-m"`:'';inner=inner.replace(/<(input|textarea|button)\b(?![^>]*\bid=)/,`<$1 id="${id}"${m}`);return `<div class="cl-field${err?' is-error':''}"><label class="cl-label" for="${id}">${label}</label>${inner}${err?`<p class="cl-msg cl-err" id="${id}-m">${ic('warn')}${err}</p>`:hint?`<p class="cl-msg" id="${id}-m">${hint}</p>`:''}</div>`;};
 const V=(...a)=>a.map(x=>x.split(':'));
 const has=(v,...k)=>k.includes(v);

 const BASE=`.cl-root{font-family:var(--cl-font);color:var(--cl-text);font-size:15px;line-height:1.45}
.cl-root *,.cl-root *::before,.cl-root *::after{box-sizing:border-box}
.cl-ic{width:18px;height:18px;flex:none}
.cl-surface{background:var(--cl-surface);border:var(--cl-bw) solid var(--cl-line);border-radius:var(--cl-radius);box-shadow:var(--cl-shadow);-webkit-backdrop-filter:var(--cl-glass);backdrop-filter:var(--cl-glass)}
.cl-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:var(--cl-h);padding:var(--cl-pad);font:var(--cl-weight) 14px/1 var(--cl-font);border-radius:var(--cl-radius);border:var(--cl-bw) solid var(--cl-line);background:var(--cl-surface);color:var(--cl-text);box-shadow:var(--cl-shadow);cursor:pointer;transition:transform .15s,filter .15s,background .15s,box-shadow .15s}
.cl-btn.primary{background:var(--cl-accent-grad);border-color:var(--cl-accent);color:var(--cl-on-accent)}
.cl-btn.danger{color:var(--cl-danger);border-color:var(--cl-danger)}
.cl-btn:hover,.cl-btn.is-hover{filter:brightness(1.06);transform:translateY(-1px)}
.cl-btn:active,.cl-btn.is-active{transform:translateY(1px) scale(.98);filter:brightness(.95)}
.cl-btn:focus-visible,.cl-btn.is-focus,.cl-focusable:focus-visible,.is-focus>.cl-focusable{outline:2px solid var(--cl-accent);outline-offset:3px}
.cl-btn[disabled],.is-disabled{opacity:.45;cursor:not-allowed;transform:none;filter:none}
.cl-btn.icon{width:var(--cl-h);padding:0}
.cl-spin{width:14px;height:14px;border-radius:50%;border:2px solid currentColor;border-right-color:transparent;animation:cl-spin .8s linear infinite}
@keyframes cl-spin{to{transform:rotate(1turn)}}
.cl-field{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;min-width:0}
.cl-root .cl-bare{width:0;min-width:0;flex:1 1 0}
.cl-label{font-size:13px;font-weight:600;color:var(--cl-text)}
.cl-input{width:100%;min-height:var(--cl-h);padding:var(--cl-pad);font:400 15px/1.3 var(--cl-font);color:var(--cl-text);background:var(--cl-surface);border:max(1px,var(--cl-bw)) solid var(--cl-line);border-radius:var(--cl-radius-sm);box-shadow:var(--cl-shadow);-webkit-backdrop-filter:var(--cl-glass);backdrop-filter:var(--cl-glass);outline:0;display:flex;align-items:center;gap:8px}
.cl-input:hover,.is-hover .cl-input{border-color:var(--cl-muted)}
.cl-input:focus,.cl-input:focus-within,.is-focus .cl-input{border-color:var(--cl-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--cl-accent) 25%,transparent)}
.is-error .cl-input{border-color:var(--cl-danger)}
.cl-msg{margin:0;font-size:12.5px;color:var(--cl-muted);display:flex;gap:6px;align-items:center}
.cl-err{color:var(--cl-danger)}.cl-err .cl-ic{width:14px;height:14px}
.cl-muted{color:var(--cl-muted)}
.cl-row{display:flex;flex-wrap:wrap;gap:var(--cl-gap);align-items:center}
.cl-stack{display:grid;gap:var(--cl-gap)}
.cl-h{font:var(--cl-weight) 18px/1.2 var(--cl-display);margin:0}
.cl-chip{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;font-size:12.5px;font-weight:600;border:1px solid var(--cl-line);background:var(--cl-surface)}
.cl-sr{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;border:0;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap}
.cl-root [hidden]{display:none!important}
.cl-root :is(a,button,input,textarea,[tabindex]):focus-visible{outline:2px solid var(--cl-accent);outline-offset:2px}
@media (prefers-reduced-motion:reduce){.cl-root *,.cl-root *::before,.cl-root *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}`;

