 /* ---------- C41–C64: interactive components ----------
    Each entry adds live(root, signal): the behaviour wired onto the first state wherever the
    component is shown live (lab "Try it" box and the catalogue detail view). Static states stay inert. */
 const Q=(r,s)=>r.querySelector(s),QA=(r,s)=>[...r.querySelectorAll(s)];
 const note=(t='',cls='')=>`<p class="cl-msg cl-note ${cls}" role="status" data-note>${t}</p>`;
 const say=(r,t,err=false)=>{const n=Q(r,'[data-note]');if(!n)return;n.classList.toggle('cl-err',!!err);n.textContent='';requestAnimationFrame(()=>n.textContent=t);};
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 const keyStep=(e,i,n,vertical=true)=>{const k=e.key;if(k==='ArrowRight'||(vertical&&k==='ArrowDown'))return (i+1)%n;if(k==='ArrowLeft'||(vertical&&k==='ArrowUp'))return (i-1+n)%n;if(k==='Home')return 0;if(k==='End')return n-1;return null;};
 const rove=(items,el)=>items.forEach(x=>x.tabIndex=x===el?0:-1);
 const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
 const onDoc=(sig,type,fn)=>document.addEventListener(type,fn,{signal:sig,capture:true});
 const later=(sig,fn,ms)=>{const t=setTimeout(fn,ms);sig.addEventListener('abort',()=>clearTimeout(t));return t;};
 const every=(sig,fn,ms)=>{const t=setInterval(fn,ms);sig.addEventListener('abort',()=>clearInterval(t));return t;};

 /* APG menu button: Enter/Space/↓ open on first item, ↑ on last; arrows, Home/End, type-ahead; Esc returns focus. */
 function menuLive(r,sig,trig,menu,onPick){
  const items=()=>QA(menu,'[role^=menuitem]:not([aria-disabled=true])');
  const open=(which=0)=>{menu.hidden=false;trig.setAttribute('aria-expanded','true');const it=items();(which<0?it[it.length-1]:it[which])?.focus();};
  const close=(f=true)=>{if(menu.hidden)return;menu.hidden=true;trig.setAttribute('aria-expanded','false');if(f)trig.focus();};
  trig.addEventListener('click',()=>menu.hidden?open(0):close());
  trig.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='Enter'||e.key===' '){e.preventDefault();open(0);}else if(e.key==='ArrowUp'){e.preventDefault();open(-1);}});
  menu.addEventListener('keydown',e=>{const it=items(),i=it.indexOf(document.activeElement),n=it.length;
   if(e.key==='Escape'){e.preventDefault();close();return;}
   if(e.key==='Tab'){close(false);return;}
   if(e.key==='Enter'||e.key===' '){e.preventDefault();document.activeElement.click();return;}
   const j=e.key==='ArrowDown'?(i+1)%n:e.key==='ArrowUp'?(i-1+n)%n:e.key==='Home'?0:e.key==='End'?n-1:null;
   if(j!=null){e.preventDefault();it[j].focus();return;}
   if(/^\S$/.test(e.key)){const k=e.key.toLowerCase();for(let s=1;s<=n;s++){const x=it[(i+s)%n];if(x.textContent.trim().toLowerCase().startsWith(k)){x.focus();break;}}}
  });
  menu.addEventListener('click',e=>{const it=e.target.closest('[role^=menuitem]');if(!it||it.getAttribute('aria-disabled')==='true')return;if(it.getAttribute('role')==='menuitemcheckbox'){it.setAttribute('aria-checked',String(it.getAttribute('aria-checked')!=='true'));onPick(it);return;}close();onPick(it);});
  onDoc(sig,'pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!trig.contains(e.target))close(false);});
 }
 const MENU_CSS='.cl-menuwrap{position:relative;display:inline-grid;gap:8px;justify-items:start;min-width:250px}.cl-menuwrap:has([aria-expanded=true]){padding-bottom:var(--mh,230px)}.cl-menu{list-style:none;margin:0;padding:6px;position:absolute;top:calc(var(--cl-h) + 6px);left:0;width:250px;max-width:calc(100vw - 48px);z-index:3;display:grid;gap:1px}.cl-menu[hidden]{display:none}.cl-menu [role^=menuitem]{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:var(--cl-radius-sm);font-size:14px;cursor:pointer;outline:0}.cl-menu [role^=menuitem]:hover,.cl-menu [role^=menuitem]:focus,.cl-menu .is-act{background:color-mix(in srgb,var(--cl-accent) 13%,transparent)}.cl-menu [role^=menuitem]:focus-visible,.cl-menu .is-act{box-shadow:inset 0 0 0 2px var(--cl-accent)}.cl-menu [role^=menuitem]>span{flex:1;display:grid;gap:1px}.cl-menu small{font-size:12px;color:var(--cl-muted)}.cl-menu kbd{font:11px ui-monospace,monospace;color:var(--cl-muted)}.cl-menu [role=separator]{height:1px;background:var(--cl-line);margin:4px 2px}.cl-menu .danger{color:var(--cl-danger)}.cl-menu .cl-ic{width:16px;height:16px;color:var(--cl-muted)}.cl-menu .danger .cl-ic{color:inherit}.cl-menu .cl-mchk{flex:none;display:inline-flex}.cl-menu [aria-checked=false] .cl-mchk{visibility:hidden}.cl-mchk .cl-ic{color:var(--cl-accent)}';
 const SEG_CSS='.cl-seg{position:relative;display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr));padding:4px;background:color-mix(in srgb,var(--cl-muted) 14%,var(--cl-surface));border:max(1px,var(--cl-bw)) solid var(--cl-line);border-radius:calc(var(--cl-radius-sm) + 4px)}.cl-seg>button{all:unset;box-sizing:border-box;position:relative;z-index:1;display:flex;align-items:center;justify-content:center;gap:6px;min-height:calc(var(--cl-h) - 8px);padding:0 10px;font:600 14px var(--cl-font);color:color-mix(in srgb,var(--cl-text) 82%,var(--cl-surface));border-radius:var(--cl-radius-sm);cursor:pointer;text-align:center;transition:color .2s;white-space:nowrap}.cl-seg>[aria-checked=true]{color:var(--cl-text)}.cl-seg>button:focus-visible,.cl-seg>.is-focus{outline:2px solid var(--cl-accent);outline-offset:1px}.cl-seg>[aria-disabled=true]{opacity:.45;cursor:not-allowed}.cl-segind{position:absolute;top:4px;bottom:4px;left:4px;width:calc((100% - 8px) / var(--n));transform:translateX(calc(var(--i) * 100%));background:var(--cl-surface);border-radius:var(--cl-radius-sm);box-shadow:0 1px 3px rgb(0 0 0 / .14),0 0 0 1px var(--cl-line);transition:transform .25s cubic-bezier(.3,.7,.2,1)}.cl-seg .cl-ic{width:16px;height:16px}';
 const SW_CSS='.cl-sw{all:unset;box-sizing:border-box;flex:none;position:relative;width:44px;height:26px;border-radius:999px;background:color-mix(in srgb,var(--cl-muted) 40%,transparent);cursor:pointer;transition:background .2s}.cl-sw i{position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgb(0 0 0 / .3);transition:transform .2s}.cl-sw[aria-checked=true]{background:var(--cl-accent)}.cl-sw[aria-checked=true] i{transform:translateX(18px)}.cl-sw:focus-visible{outline:2px solid var(--cl-accent);outline-offset:2px}.cl-sw[aria-disabled=true]{opacity:.55;cursor:not-allowed}';
 const sw=(on,attr='')=>`<button type="button" role="switch" class="cl-sw" aria-checked="${on}" ${attr}><i></i></button>`;
 const pw=s=>{const t=[s.length>=12,/[a-z]/.test(s)&&/[A-Z]/.test(s),/\d/.test(s),/[^A-Za-z0-9]/.test(s)];const n=s?t.filter(Boolean).length:0;return {t,n,label:s?['Very weak','Weak','Fair','Good','Strong'][n]:'Strength',tip:s?[' · Add length and variety.',' · Add more length and a number.',' · Add a symbol or more length.',' · Nearly there.',' · Hard to guess.'][n]:' · Use 12 or more characters.'};};
 const pwReqs=s=>{const r=pw(s);return ['12 or more characters','Upper and lower case','A number','A symbol'].map((t,i)=>`<li class="${r.t[i]?'ok':''}">${ic(r.t[i]?'check':'dot')}<span>${t}</span><span class="cl-sr">${r.t[i]?'done':'not yet'}</span></li>`).join('');};
 const hsv2hex=(h,s,v)=>{const f=n=>{const k=(n+h/60)%6;return v-v*s*Math.max(0,Math.min(k,4-k,1));};return '#'+[f(5),f(3),f(1)].map(x=>Math.round(x*255).toString(16).padStart(2,'0')).join('');};
 const hex2hsv=hex=>{let m=hex.replace('#','');if(m.length===3)m=m.split('').map(c=>c+c).join('');const [r,g,b]=[0,2,4].map(i=>parseInt(m.slice(i,i+2),16)/255);const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;let h=0;if(d){h=mx===r?((g-b)/d)%6:mx===g?(b-r)/d+2:(r-g)/d+4;h=(h*60+360)%360;}return [Math.round(h),mx?d/mx:0,mx];};
 const lum=hex=>{const m=hex.replace('#','');return [0,2,4].map(i=>parseInt(m.slice(i,i+2),16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4).reduce((a,x,i)=>a+x*[.2126,.7152,.0722][i],0);};
 const contrastNote=hex=>{const L=lum(hex),w=1.05/(L+.05),k=(L+.05)/.05,best=w>=k?['White',w]:['Black',k];return `${best[0]} text on this colour: ${best[1].toFixed(1)}:1 · ${best[1]>=7?'AAA':best[1]>=4.5?'AA':best[1]>=3?'AA large text only':'fails'}`;};
 const hueName=h=>h<15||h>=345?'red':h<45?'orange':h<70?'yellow':h<165?'green':h<195?'cyan':h<255?'blue':h<290?'violet':'pink';
 const mmss=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
 const CODE={css:['.card {','  border-radius: var(--radius);','  padding: 16px 20px;','  /* lift on hover */','  transition: transform .2s ease;','}','.card:hover { transform: translateY(-2px); }'],html:['<article class="card">','  <h3>Garden Notes</h3>','  <a href="/boards/garden">Open board</a>','</article>'],react:['export function Card({ title, href }) {','  return (','    <article className="card">','      <h3>{title}</h3>','      <a href={href}>Open board</a>','    </article>','  );','}']};
 const hl=(line,lang)=>esc(line).replace(/(\/\*.*?\*\/)|(&quot;.*?&quot;|'.*?')|\b(\d+(?:px|s)?|\.\d+s)\b|\b(export|function|return|const)\b/g,(m,c,s,n,k)=>c?`<span class="t-c">${c}</span>`:s?`<span class="t-s">${s}</span>`:n?`<span class="t-n">${n}</span>`:`<span class="t-k">${k}</span>`);
 const codeHTML=lang=>CODE[lang].map(l=>`<span class="cl-ln">${hl(l,lang)}</span>`).join('\n');
