   const pick=b=>{bs.forEach(x=>x.setAttribute('aria-checked',String(x===b)));rove(bs,b);g.style.setProperty('--i',bs.indexOf(b));b.focus();say(r,'Showing '+M[b.textContent.trim()]);};
