   kb.addEventListener('click',e=>{const b=e.target.closest('.cl-kbmv .cl-btn');if(!b)return;const card=b.closest('.cl-kbcard'),ci=cols.indexOf(card.closest('.cl-kbcol')),dir=QA(card,'.cl-kbmv .cl-btn').indexOf(b);moveTo(card,ci+(dir?1:-1),dir);});
